SELECT

FROM DepositTransHistory a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.currency = #{currency}


    AND a.blockchain = #{blockchain}


    AND a.depositAddress = #{depositAddress}


    AND a.transId = #{transId}


    AND a.amount = #{amount}


    AND a.netFee = #{netFee}


    AND a.confirmState = #{confirmState}


    AND a.depositState = #{depositState}


    AND a.remark = #{remark}


    AND a.createTime = #{createTime}


    AND a.updateBy = #{updateBy}


    AND a.updateTime = #{updateTime}

limit 1

SELECT

FROM DepositTransHistory a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.currency LIKE CONCAT('%',#{currency}, '%')


    AND a.blockchain LIKE CONCAT('%',#{blockchain}, '%')


    AND a.depositAddress LIKE CONCAT('%',#{depositAddress}, '%')


    AND a.transId LIKE CONCAT('%',#{transId}, '%')


    AND a.amount = #{amount}


    AND a.netFee = #{netFee}


    AND a.confirmState LIKE CONCAT('%',#{confirmState}, '%')


    AND a.depositState LIKE CONCAT('%',#{depositState}, '%')


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.createTime = #{createTime}


    AND a.updateBy LIKE CONCAT('%',#{updateBy}, '%')


    AND a.updateTime = #{updateTime}
